import { flow } from 'fp-ts-esm/function';
import type { TextNode } from 'parse5';

import type { Rule } from '../core/models.js';
import type { Interceptor } from '../core/parser.js';
import { parser } from '../core/parser.js';
import {
  aToAnchor,
  aToLink,
  backgroundStyleToTextHighlight,
  colorStyleToTextColor,
  hToHeading,
  lToList,
  pToParagraph,
  spanToMention,
  spanToSpoiler,
  strongEmUStrikeToDecoration,
  textToText,
} from '../core/rules.js';
import { preprocess } from './preprocess.js';

const noEmptyLineText: Rule = [
  node => textToText[0](node) && (node as TextNode).value !== '\n',
  textToText[1],
];

export const fromRichTextHtml = (s: string, interceptor: Interceptor = ({ result }) => result) =>
  flow(
    () => preprocess(s),
    parser(
      [
        noEmptyLineText,
        pToParagraph,
        lToList,
        hToHeading,
        aToLink,
        aToAnchor,
        strongEmUStrikeToDecoration,
        colorStyleToTextColor,
        spanToMention,
        spanToSpoiler,
        backgroundStyleToTextHighlight,
      ],
      interceptor
    )
  )();
