const toConstantCase = (str: string) => toSnakeCase(str).toUpperCase();

const supportedContainerDataAlignments = [
  PluginContainerData_Alignment.CENTER,
  PluginContainerData_Alignment.LEFT,
  PluginContainerData_Alignment.RIGHT,
];

export const convertBlockDataToRicos = (type: string, data: $TSFixMe): $TSFixMe => {
  const newData = cloneDeep(data);
  const converters = {
    [VIDEO_TYPE]: convertVideoData,
    [VIDEO_TYPE_LEGACY]: convertLegacyVideoData,
    [AUDIO_TYPE]: convertAudioData,
    [DIVIDER_TYPE]: convertDividerData,
    [FILE_UPLOAD_TYPE]: convertFileData,
    [GIPHY_TYPE]: convertGIFData,
    [IMAGE_TYPE]: convertImageData,
    [IMAGE_TYPE_LEGACY]: convertImageData,
    [POLL_TYPE]: convertPollData,
    [APP_EMBED_TYPE]: convertAppEmbedData,
    [LINK_PREVIEW_TYPE]: convertLinkPreviewData,
    [MENTION_TYPE]: convertMentionData,
    [LINK_BUTTON_TYPE]: convertButtonData,
    [ACTION_BUTTON_TYPE]: convertButtonData,
    [COLLAPSIBLE_LIST_TYPE]: convertCollapsibleListData,
    [HTML_TYPE]: convertHTMLData,
    [EMBED_TYPE]: convertEmbedData,
    [LINK_TYPE]: convertLinkData,
    [TABLE_TYPE]: convertTableData,
    [GALLERY_TYPE]: convertGalleryData,
    [EXTERNAL]: convertExternalData,
  };
  let blockType = type;
  if (type === LINK_PREVIEW_TYPE && data.html) {
    blockType = EMBED_TYPE;
  }
  if ([IMAGE_TYPE_LEGACY, IMAGE_TYPE].includes(type) && !newData.config) {
    newData.config = {};
  }
  if (newData.config && blockType !== EXTERNAL) {
    convertContainerData(newData, blockType);
  }
  if (blockType in converters) {
    const convert = converters[blockType as keyof typeof converters];
    convert(newData, blockType);
  }
  const fromJSON = (data: $TSFixMe) => {
    const pluginDataMethods = TO_RICOS_DATA[blockType as keyof typeof TO_RICOS_DATA];
    return pluginDataMethods?.fromJSON(data) || data;
  };
  return fromJSON(newData);
};

const convertContainerData = (
  data: { config?: ComponentData['config']; containerData: $TSFixMe; src: $TSFixMe },
  blockType: string
) => {
  const { size, alignment, width, spoiler, height, textWrap = WRAP } = data.config || {};
  const { enabled, description, buttonContent } = spoiler || {};
  const newSpoiler: PluginContainerData_Spoiler | undefined = spoiler && {
    enabled: enabled || false,
    description,
    buttonText: buttonContent,
  };
  const normalizedAlignment = alignment?.toUpperCase();

  data.containerData = {
    alignment:
      normalizedAlignment &&
      supportedContainerDataAlignments.includes(
        normalizedAlignment as PluginContainerData_Alignment
      )
        ? normalizedAlignment
        : null,
    spoiler: newSpoiler,
    textWrap: textWrap !== NO_WRAP,
  };
  typeof height === 'number' &&
    (data.containerData.height = { custom: parseInt(height.toString(), 10) });

  if (typeof width === 'number' && (blockType !== IMAGE_TYPE || !size || size === 'inline')) {
    data.containerData.width = { custom: parseInt(width.toString(), 10) };
  } else if (size) {
    const validSize =
      PluginContainerData_Width_Type[
        toConstantCase(size) as keyof typeof PluginContainerData_Width_Type
      ];
    data.containerData.width = { size: validSize ?? PluginContainerData_Width_Type.CONTENT };
  }

  if (blockType === ACTION_BUTTON_TYPE || blockType === LINK_BUTTON_TYPE) {
    if (width === 'fit-content') {
      data.containerData.width = { size: 'ORIGINAL' };
    }
  }

  if (
    blockType === IMAGE_TYPE &&
    data.containerData.width?.size === 'ORIGINAL' &&
    data.src?.width &&
    typeof data.src.width === 'number' &&
    data.src.width > 350
  ) {
    data.containerData.alignment = data.containerData.alignment || 'CENTER';
  }
};

const convertVideoData = (data: {
  src?: string | VideoComponentData;
  metadata?: {
    oembed?: {
      thumbnail_url?: string;
      thumbnail_width?: string;
      thumbnail_height?: string;
      video_url?: string;
      title?: string;
    };
    thumbnail_url?: string;
    width?: number;
    height?: number;
    title?: string;
  };
  video: $TSFixMe;
  thumbnail: $TSFixMe;
  title?: $TSFixMe;
  duration?: number;
}) => {
  if (typeof data.src === 'string' && data.src) {
    data.video = { src: { url: data.src } };
    const {
      oembed,
      thumbnail_url,
      width: thumbnail_width,
      height: thumbnail_height,
      title,
    } = data.metadata || {};
    let src, width, height;
    if (oembed) {
      const { thumbnail_url, thumbnail_width, thumbnail_height } = oembed;
      src = thumbnail_url ? { url: thumbnail_url } : undefined;
      width = thumbnail_width;
      height = thumbnail_height;
    } else {
      src = thumbnail_url ? { url: thumbnail_url } : undefined;
      width = thumbnail_width;
      height = thumbnail_height;
    }
    const titleResolved = oembed ? oembed.title : title;
    titleResolved && (data.title = titleResolved);
    data.thumbnail = src || width || height ? { src, width, height } : undefined;
  } else if (typeof data.src === 'object' && data.src.pathname) {
    data.video = { src: { id: data.src.pathname } };
    data.thumbnail = data.src.thumbnail
      ? {
          src: { id: data.src.thumbnail.pathname },
          width: data.src.thumbnail.width,
          height: data.src.thumbnail.height,
        }
      : undefined;
  }
  data.video && (data.video.duration = data.duration);
};

const convertLegacyVideoData = (data: {
  url?: string;
  src?: string;
  oembed?: {
    thumbnail_url?: string;
    thumbnail_width?: string;
    thumbnail_height?: string;
    video_url?: string;
    width?: number;
    height?: number;
    title?: string;
  };
}) => {
  const { url, oembed, src } = data;

  if (url ?? src) {
    (data as VideoData).video = { src: { url: url ?? src } };
  }

  delete data.url;

  if (oembed) {
    const { thumbnail_url, thumbnail_width, thumbnail_height, title } = oembed;

    if (thumbnail_url) {
      (data as VideoData).thumbnail = {
        src: { url: thumbnail_url },
        width: thumbnail_width ? Number(thumbnail_width) : undefined,
        height: thumbnail_height ? Number(thumbnail_height) : undefined,
      };
    }

    if (title) {
      (data as VideoData).title = oembed.title;
    }
    delete data.oembed;
  }
  (data as VideoData).containerData = {
    alignment: PluginContainerData_Alignment.CENTER,
    textWrap: true,
  };
};

const convertAudioData = (data: AudioComponentData & { coverImage: { file_name: string } }) => {
  const { coverImage } = data;
  if (coverImage) {
    const { file_name, width, height } = coverImage;
    data.coverImage = { file_name, src: { id: file_name }, width, height };
  }
};

const convertGalleryStyles = (styles: $TSFixMe) => {
  styles.layout = {};
  styles.item = {};
  styles.thumbnails = {};
  styles?.galleryLayout !== undefined && (styles.layout.type = styles.galleryLayout);
  styles?.oneRow !== undefined && (styles.layout.horizontalScroll = styles.oneRow);
  styles?.isVertical !== undefined &&
    (styles.layout.orientation = styles.isVertical ? 'COLUMNS' : 'ROWS');
  styles?.m_numberOfImagesPerRow !== undefined &&
    (styles.layout.mobileNumberOfColumns = styles.m_numberOfImagesPerRow);

  if (
    styles?.m_numberOfImagesPerRow !== undefined &&
    !isNaN(parseInt(styles.m_numberOfImagesPerRow, 10))
  ) {
    styles.layout.mobileNumberOfColumns = styles.m_numberOfImagesPerRow;
  }

  if (styles?.gallerySizePx !== undefined && !isNaN(parseInt(styles.gallerySizePx, 10))) {
    styles.item.targetSize = styles.gallerySizePx;
  }

  if (
    styles?.numberOfImagesPerRow !== undefined &&
    !isNaN(parseInt(styles.numberOfImagesPerRow, 10))
  ) {
    styles.layout.numberOfColumns = styles.numberOfImagesPerRow;
  }

  if (styles?.cubeRatio !== undefined) {
    if (typeof styles.cubeRatio === 'string') {
      const [x, y] = styles.cubeRatio.split('/');
      if (!(Number.isNaN(parseInt(x, 10)) && Number.isNaN(parseInt(y, 10)))) {
        styles.item.ratio = Math.trunc((parseInt(x, 10) / parseInt(y, 10)) * 100) / 100;
      }
    } else {
      styles.item.ratio = styles.cubeRatio;
    }
  }

  const cubeType = styles?.cubeType?.toUpperCase();
  ['FIT', 'FILL'].includes(cubeType) && (styles.item.crop = cubeType);

  if (styles?.imageMargin !== undefined && !isNaN(parseInt(styles.imageMargin, 10))) {
    styles.item.spacing = styles.imageMargin;
  }

  const thumbnailPlacement = styles?.galleryThumbnailsAlignment?.toUpperCase();
  styles.thumbnails.placement = ['TOP', 'BOTTOM', 'LEFT', 'RIGHT'].includes(thumbnailPlacement)
    ? thumbnailPlacement
    : 'NONE';

  if (styles?.thumbnailSpacings !== undefined && !isNaN(parseInt(styles.thumbnailSpacings, 10))) {
    styles.thumbnails.spacing = Math.trunc(styles.thumbnailSpacings);
  }

  return styles;
};

const convertGalleryItem = (item: $TSFixMe) => {
  const {
    url,
    metadata: { type = 'image', poster, height, width, link, title, altText },
  } = item;
  item[type] = { media: { src: { url }, height, width } };
  title && (item.title = title);
  altText && (item.altText = altText);
  if (type === 'video' && poster) {
    const src = { url: poster.url || poster };
    item.video.thumbnail = { src, height: poster.height || height, width: poster.width || width };
  }
  type === 'image' && link && (item.image.link = createLink(link));

  return item;
};

const convertGalleryData = (data: GalleryData & { styles: DraftGalleryStyles }) => {
  data?.items !== undefined && (data.items = data.items.map(item => convertGalleryItem(item)));
  data?.styles !== undefined && (data.options = convertGalleryStyles(data.styles));
};

const convertDividerData = (data: {
  type?: string;
  config?: ComponentData['config'];
  lineStyle?: string;
  width: $TSFixMe;
  alignment: $TSFixMe;
  containerData: $TSFixMe;
}) => {
  data?.type !== undefined && (data.lineStyle = data.type?.toUpperCase());
  data?.config?.size !== undefined && (data.width = data.config?.size?.toUpperCase());
  data?.config?.alignment !== undefined && (data.alignment = data.config?.alignment?.toUpperCase());
  data.containerData.width = { size: PluginContainerData_Width_Type.CONTENT };
};

const convertExternalData = (data: $TSFixMe) => {
  data.fields = convertJsonToStruct(data).fields;
};

const convertImageData = (data: {
  src?: ImageComponentData;
  config?: ComponentData['config'];
  metadata?: { alt?: string; caption?: string };
  image: $TSFixMe;
  link: $TSFixMe;
  altText: $TSFixMe;
  caption: $TSFixMe;
  width: $TSFixMe;
  height: $TSFixMe;
}) => {
  if (isNaN(parseInt(data.width))) {
    delete data.width;
  }

  if (isNaN(parseInt(data.height))) {
    delete data.height;
  }

  if (typeof data.src === 'string') {
    data.image = {
      src: { source: 'static', url: data.src },
      width: ensureValidNumber(data.width),
      height: ensureValidNumber(data.height),
    };
  } else if (typeof data.src === 'object' && data.src !== null) {
    if ('url' in data.src && typeof data.src.url === 'string') {
      const { url, width, height } = data.src || {};
      data.image = {
        src: { url },
        width: ensureValidNumber(width),
        height: ensureValidNumber(height),
      };
    } else if (
      'file_name' in data.src &&
      typeof data.src.file_name === 'string' &&
      data.src.file_name
    ) {
      const { file_name, width, height } = data.src || {};
      data.image = {
        src: { id: file_name },
        width: ensureValidNumber(width),
        height: ensureValidNumber(height),
      };
    }
  }

  const { link, anchor } = data.config || {};
  data.link = (link || anchor) && createLink({ ...link, anchor });
  data.altText = data.metadata?.alt;
  data.caption = data.metadata?.caption;
};

const convertGIFData = (
  data: GIFData & {
    gif?: {
      originalUrl: $TSFixMe;
      originalMp4: $TSFixMe;
      stillUrl: $TSFixMe;
      downsizedUrl: $TSFixMe;
      downsizedSmallMp4: $TSFixMe;
      downsizedStillUrl: $TSFixMe;
      height: $TSFixMe;
      width: $TSFixMe;
    };
  }
) => {
  const { gif } = data;
  const {
    originalUrl,
    originalMp4,
    stillUrl,
    downsizedUrl,
    downsizedSmallMp4,
    downsizedStillUrl,
    height,
    width,
  } = gif || {};
  data.original = { gif: originalUrl, mp4: originalMp4, still: stillUrl };
  data.downsized = { gif: downsizedUrl, mp4: downsizedSmallMp4, still: downsizedStillUrl };
  data.height = height;
  data.width = width;
  delete data.gif;
};

const convertPollData = (data: {
  containerData: $TSFixMe;
  layout: $TSFixMe;
  design: $TSFixMe;
  poll: $TSFixMe;
}) => {
  data?.layout?.poll?.type !== undefined &&
    (data.layout.poll.type = data.layout.poll.type.toUpperCase());
  data?.layout?.poll?.direction !== undefined &&
    (data.layout.poll.direction = data.layout.poll.direction.toUpperCase());
  if (data?.layout?.option !== undefined) {
    data.layout.options = data.layout.option;
    delete data.layout.option;
  }
  if (data?.design !== undefined) {
    const { poll = {}, option = {} } = data.design;
    const { backgroundType, background } = poll;
    const regex = /(\d*)px/;
    const getBackground = (background: $TSFixMe) =>
      background?.angle
        ? {
            gradient: {
              angle: background.angle,
              startColor: background?.start?.toUpperCase(),
              lastColor: background.end?.toUpperCase(),
            },
          }
        : background?.charAt?.(0) === '#'
          ? { color: background?.toUpperCase() }
          : { image: { src: { url: background } } };
    data.design = {
      poll: {
        background: {
          type: backgroundType?.toUpperCase(),
          ...getBackground(background),
        },
        borderRadius: parseInt(regex.exec(poll.borderRadius)?.[1] || '0'),
      },
      options: { borderRadius: parseInt(regex.exec(option.borderRadius)?.[1] || '0') },
    };
  }
  data?.poll?.id !== undefined && (data.poll.pollId = data.poll.id);
  data?.poll?.createdBy !== undefined && (data.poll.creatorId = data.poll.createdBy);
  data?.poll?.mediaId !== undefined && (data.poll.image = { src: { url: data.poll.mediaId } });
  data?.poll?.options !== undefined &&
    (data.poll.options = data.poll.options.map(({ mediaId, ...rest }: $TSFixMe) => ({
      image: { src: { url: mediaId } },
      ...rest,
    })));
  if (data?.poll?.settings !== undefined) {
    const { multipleVotes, voteRole, resultsVisibility, votersDisplay, votesDisplay } =
      data.poll.settings;

    const getViewRole = (resultsVisibility: $TSFixMe) =>
      resultsVisibility === 'ALWAYS'
        ? 'EVERYONE'
        : resultsVisibility === 'VOTERS_ONLY'
          ? 'VOTERS'
          : 'CREATOR';

    data.poll.settings = {
      permissions: {
        view: getViewRole(resultsVisibility),
        vote: voteRole,
        allowMultipleVotes: multipleVotes,
      },
      showVoters: votersDisplay,
      showVotesCount: votesDisplay,
    };
  }
  data?.containerData?.width?.size !== undefined && (data.containerData.width.size = 'CONTENT');
};

const convertAppEmbedData = (data: {
  type: string;
  selectedProduct: Record<string, string>;
  url: $TSFixMe;
  imageSrc: $TSFixMe;
  imageWidth: $TSFixMe;
  imageHeight: $TSFixMe;
  itemId: $TSFixMe;
  name: $TSFixMe;
  bookingData: $TSFixMe;
  eventData: $TSFixMe;
  image: $TSFixMe;
}) => {
  const {
    id,
    name,
    imageSrc,
    imageHeight,
    imageWidth,
    description,
    pageUrl,
    scheduling,
    location,
    html,
    durations,
  } = data.selectedProduct;
  data.url = pageUrl || (html && (data.url = html.match(/href="[^"]*/g)?.[0]?.slice(6)));
  data.itemId = id;
  data.name = name;
  data.image = { src: { url: imageSrc }, width: imageWidth, height: imageHeight };
  if (data.type === 'booking') {
    data.bookingData = { durations: durations || description };
  } else if (data.type === 'event') {
    data.eventData = {
      location: location || (description && description.match(/[^|]*$/)?.[0]),
      scheduling: scheduling || (description && description.match(/[^|]+/)?.[0]),
    };
  }
  data.type = data.type?.toUpperCase();
};

const convertLinkPreviewData = (data: {
  thumbnail_url?: string;
  config?: { link: $TSFixMe };
  thumbnailUrl: $TSFixMe;
  link: $TSFixMe;
}) => {
  data?.thumbnail_url !== undefined && (data.thumbnailUrl = data.thumbnail_url);
  data.config?.link && (data.link = createLink(data.config?.link));
};

const convertMentionData = (data: {
  mention?: { name?: string; slug?: string; id: string };
  name?: string;
  slug?: string;
  id?: string;
}) => {
  data.name = data.mention?.name;
  data.slug = data.mention?.slug;
  data.id = data.mention?.id;
  delete data.mention;
};

const convertFileData = (data: FileComponentData & FileData) => {
  const { url, id, privacy, size } = data;
  const isPrivate = typeof privacy !== 'undefined' ? privacy === 'private' : undefined;
  const src: FileSource = { url, id, private: isPrivate };
  data.src = src;

  if (size) {
    data.sizeInKb = toSizeInKb(size);

    const FILE_MAX_SIZE_IN_BYTES = 2e9; // 2GB
    data.size = Math.min(size, FILE_MAX_SIZE_IN_BYTES);
  }
};

const convertCollapsibleListData = (data: {
  config?: {
    expandState: string;
    expandOnlyOne: boolean;
    direction: string;
    isQapageData?: boolean;
  };
  initialExpandedItems?: string;
  expandOnlyOne?: boolean;
  direction?: string;
  isQapageData?: boolean;
}) => {
  const { config } = data || {};
  const { expandState, expandOnlyOne, direction, isQapageData } = config || {};

  const getInitialExpandedItems = (expandState?: string) => {
    if (expandState === 'expanded') {
      return 'ALL';
    }
    if (expandState === 'collapsed') {
      return 'NONE';
    }
    return 'FIRST';
  };

  data.initialExpandedItems = getInitialExpandedItems(expandState);
  data.expandOnlyOne = expandOnlyOne;
  data.isQapageData = isQapageData;
  data.direction = direction?.toUpperCase();
};

const convertButtonData = (
  data: { button?: { settings: $TSFixMe; design: $TSFixMe } } & ButtonData,
  blockType: string
) => {
  const { settings, design } = data.button || {};
  const { borderRadius, borderWidth, background, backgroundColor, color, borderColor } =
    design || {};
  const { buttonText, url, rel, target } = settings || {};

  data.styles = {
    colors: { text: color, border: borderColor, background: background || backgroundColor },
    border: {
      radius: roundNumericValue(borderRadius),
      width: roundNumericValue(borderWidth),
    },
  };
  data.type = blockType === ACTION_BUTTON_TYPE ? ButtonData_Type.ACTION : ButtonData_Type.LINK;
  data.text = buttonText;
  if (data.type === ButtonData_Type.LINK && url) {
    data.link = createLink({
      url,
      rel,
      target,
    });
  }
};

const convertHTMLData = (data: $TSFixMe) => {
  const { src, srcType, config } = data;
  if (config?.isAdsense) {
    data.source = HTMLData_Source.ADSENSE;
  }
  data[srcType] = src;
};

const convertEmbedData = (data: {
  html: $TSFixMe;
  description?: $TSFixMe;
  title?: $TSFixMe;
  thumbnail_url?: $TSFixMe;
  src: $TSFixMe;
  config: $TSFixMe;
  oembed: $TSFixMe;
}) => {
  const url = data.config?.link?.url;
  url && (data.src = url);
  data.oembed = {
    type: 'rich',
    thumbnailUrl: data.thumbnail_url,
    title: data.title,
    description: data.description,
    html: data.html,
  };
};

const convertLinkData = (data: { url: string; target?: string; rel?: string } & { link: Link }) => {
  data.link = createLink(data);
};

const convertTableData = (data: $TSFixMe) => {
  const {
    config: { colsWidth, rowsHeight, colsMinWidth, rowHeader, colHeader },
  } = data;
  const colsWidthRatio = colsWidth.map((width: $TSFixMe) => parseInt(width, 10));
  data.dimensions = { colsWidthRatio, rowsHeight, colsMinWidth };
  data.rowHeader = rowHeader;
  data.columnHeader = colHeader;
};

const ensureValidNumber = (value: number | string) => {
  if (!value) {
    return value;
  }

  const stringValue = value?.toString();

  if (stringValue.endsWith('%')) {
    // None of the viewers/editors support percentage values.
    // Default to some constant value, just to ensure it's rendered.
    // We have 0.00003% of content like this, which now don't even render.
    return 1000;
  }

  const numberValue = parseInt(value?.toString(), 10);
  if (isNaN(numberValue)) {
    return undefined;
  }

  return numberValue;
};
