import omitDeep from 'omit-deep';

import { cloneDeep } from './../../_shared/clone-deep.js';
import { deepEqual } from './../../_shared/deep-equal.js';
import { omitKeys } from './../../_shared/omit-keys.js';
import { pickKeys } from './../../_shared/pick-keys.js';

import type { DraftContent } from '../index.js';
import type { RawDraftEntityRange } from '../types/draft-js.js';
import { fromEntries } from '../utils.js';

const IGNORED_KEYS = [
  'updatedTimestamp',
  'createdTimestamp',
  'tempData',
  'isCustomVideo',
  'VERSION',
];
const IGNORED_POLL_CONFIG_KEYS = ['alignment', 'size', 'width'];
const IGNORED_SRC_KEYS = ['id', 'original_file_name'];
const IGNORED_BUTTON_DESIGN_KEYS = ['activeButton', 'padding'];
const OEMBED_KEYS = ['thumbnail_url', 'width', 'height'];

const isObject = (value: unknown): value is object => value !== null && typeof value === 'object';

/**
 * Deep diff between two objects.
 * @param object Object compared
 * @param base   Object to compare to
 * @return       Return a new object that represents the diff
 */
export function compare(
  object: any,
  base: any,
  options: { verbose?: boolean; ignoredKeys?: string[] } = {}
) {
  const { verbose, ignoredKeys } = options;
  const allIgnoredKeys = [...IGNORED_KEYS, ...(ignoredKeys || [])];

  const objectWithoutIgnored: $TSFixMe = omitDeep(cloneDeep(object), allIgnoredKeys);
  const basetWithoutIgnored: $TSFixMe = omitDeep(cloneDeep(base), allIgnoredKeys);

  objectWithoutIgnored.blocks && removeEmoji(objectWithoutIgnored);
  basetWithoutIgnored.blocks && removeEmoji(basetWithoutIgnored);

  const ARE_EQUAL = {};

  const getChanges = (value: $TSFixMe, base: $TSFixMe): $TSFixMe => {
    if (value === base) {
      return ARE_EQUAL;
    } else if (deepEqual(value, base, comparator)) {
      return ARE_EQUAL;
    } else if (Array.isArray(value) && Array.isArray(base)) {
      const items = value
        .map((valueItem, i) => getChanges(valueItem, base[i]))
        .filter(item => item !== ARE_EQUAL);
      if (items.length) {
        return items;
      } else {
        return ARE_EQUAL;
      }
    } else if (isObject(value) && isObject(base)) {
      const keys = Array.from(new Set<string>([...Object.keys(value), ...Object.keys(base)]));
      const entries = keys
        .map(key => [
          key,
          getChanges(value[key as keyof typeof value], base[key as keyof typeof base]),
        ])
        .filter(([_, result]) => result !== ARE_EQUAL);
      if (entries.length) {
        return Object.fromEntries(entries);
      } else {
        return ARE_EQUAL;
      }
    } else {
      return value;
    }
  };

  const result = getChanges(objectWithoutIgnored, basetWithoutIgnored);

  if (verbose && result !== ARE_EQUAL) {
    console.dir(result); // oxlint-disable-line no-console
  }

  return result;
}

const comparator = (leftValue: unknown, rightValue: unknown, key?: PropertyKey) => {
  const left = leftValue as Record<string, any> | undefined;
  const right = rightValue as Record<string, any> | undefined;
  if (left?.enableVoteRole !== undefined || right?.enableVoteRole !== undefined) {
    return deepEqual(
      omitKeys(left, IGNORED_POLL_CONFIG_KEYS),
      omitKeys(right, IGNORED_POLL_CONFIG_KEYS)
    );
  }
  if (left?.thumbnail_url || right?.thumbnail_url) {
    return deepEqual(pickKeys(left, OEMBED_KEYS), pickKeys(right, OEMBED_KEYS));
  }
  if (key === 'src') {
    return deepEqual(omitKeys(left, IGNORED_SRC_KEYS), omitKeys(right, IGNORED_SRC_KEYS));
  }
  if (key === 'design') {
    return deepEqual(
      omitKeys(left, IGNORED_BUTTON_DESIGN_KEYS),
      omitKeys(right, IGNORED_BUTTON_DESIGN_KEYS)
    );
  }
  if (key === 'link' && (right?.rel === 'noopener' || left?.rel === 'noopener')) {
    return deepEqual(omitKeys(left, ['rel']), omitKeys(right, ['rel']));
  }
  return undefined;
};

const removeEmoji = (object: DraftContent) => {
  const emojiEntityKeys: number[] = [];
  Object.entries<any>(object.entityMap).forEach(
    ([key, value]) => value.type === 'EMOJI_TYPE' && emojiEntityKeys.push(parseInt(key, 10))
  );
  object.entityMap = fromEntries(
    Object.entries(object.entityMap).filter(([, value]) => value.type !== 'EMOJI_TYPE')
  );
  object.blocks = object.blocks.map(block => ({
    ...block,
    entityRanges: (block.entityRanges as RawDraftEntityRange[]).filter(
      (range: RawDraftEntityRange) => !emojiEntityKeys.includes(range.key)
    ),
  }));
};
