import * as A from 'fp-ts-esm/Array';
import { flow, identity, pipe } from 'fp-ts-esm/function';
import type * as J from 'fp-ts-esm/Json';
import { concatAll } from 'fp-ts-esm/Monoid';
import * as R from 'fp-ts-esm/Record';
import { first } from 'fp-ts-esm/Semigroup';
import * as T from 'fp-ts-esm/Tuple';

import type { ListValue, Struct, Value } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { NullValue } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { firstRight } from '../../../fp-utils.js';

const valueM = R.getMonoid(first<Value>());
const toRecord = ([k, v]: [string, Value]): Record<string, Value> => ({ [k]: v });
const toStruct = (fields: Record<string, Value>): Struct => ({ fields });
const toListValue = (values: Value[]): ListValue => ({ values });

const defaultValue = {
  numberValue: undefined,
  nullValue: undefined,
  stringValue: undefined,
  boolValue: undefined,
};

const convertJsonToList = (json: J.JsonArray): ListValue =>
  pipe(json as any[], A.map(convertJsonToValue), toListValue);

// Explicit type args: TS 7 infers `T` from the resolver branches (narrow
// object literals) instead of widening to `Value`, rejecting the default.
const convertJsonToValue = (json: J.Json): Value =>
  firstRight<J.Json, Value>(json, { ...defaultValue, nullValue: NullValue.NULL_VALUE }, [
    [json => typeof json === 'number', json => ({ ...defaultValue, numberValue: json as number })],
    [json => typeof json === 'string', json => ({ ...defaultValue, stringValue: json as string })],
    [json => typeof json === 'boolean', json => ({ ...defaultValue, boolValue: json as boolean })],
    [
      json => Array.isArray(json),
      json => ({ ...defaultValue, listValue: convertJsonToList(json as J.JsonArray) }),
    ],
    [
      json => json !== null && typeof json === 'object',
      json => ({ ...defaultValue, structValue: convertJsonToStruct(json as J.JsonRecord) }),
    ],
  ]);

export const convertJsonToStruct: (json: J.JsonRecord) => Struct = flow(
  Object.entries,
  A.map(T.bimap(convertJsonToValue, identity)),
  A.map(toRecord),
  concatAll(valueM),
  toStruct
);
