import type { Node, RichContent } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { ensureNodeType, toHtml } from '../../converters/html/toHtml/to-html.js';
import { firstRight } from '../../fp-utils.js';
import { extract } from '../../RicosContentAPI/extract.js';
import type {
  DataFieldNamesWithContainerData,
  NonTextualNode,
  NonTextualTranslatable,
  TextualNode,
  TextualTranslatable,
  Translatable,
} from '../types.js';
import { getDataFieldName, getDataFieldValue, isType } from '../utils.js';
import { fieldsToTranslatables } from './fields-to-translatables.js';
import {
  toAppEmbedTranslatable,
  toButtonTranslatable,
  toGalleryTranslatable,
  toHtmlTranslatable,
  toImageTranslatable,
  toLinkPreviewTranslatable,
  toPollTranslatable,
  toVideoTranslatable,
} from './plugins-to-translatables.js';

export const toTranslatables = ({ nodes }: RichContent) => {
  const nodesWithType = ensureNodeType(nodes ?? []);
  return [
    ...nodeDataTranslatables(nodesWithType),
    ...nodeContainerDataTranslatables(nodesWithType),
  ];
};

const nodeDataTranslatables = (nodes: Node[]): Translatable[] =>
  extract(nodes)
    .map(node =>
      firstRight(node, [] as Translatable[], [
        [isType(Node_Type.HEADING), getTextualContent as (node: Node) => Translatable[]],
        [isType(Node_Type.PARAGRAPH), getTextualContent as (node: Node) => Translatable[]],
        [isType(Node_Type.APP_EMBED), toAppEmbedTranslatable as (node: Node) => Translatable[]],
        [isType(Node_Type.BUTTON), toButtonTranslatable as (node: Node) => Translatable[]],
        [isType(Node_Type.GALLERY), toGalleryTranslatable as (node: Node) => Translatable[]],
        [isType(Node_Type.HTML), toHtmlTranslatable as (node: Node) => Translatable[]],
        [isType(Node_Type.IMAGE), toImageTranslatable as (node: Node) => Translatable[]],
        [
          isType(Node_Type.LINK_PREVIEW),
          toLinkPreviewTranslatable as (node: Node) => Translatable[],
        ],
        [isType(Node_Type.POLL), toPollTranslatable as (node: Node) => Translatable[]],
        [isType(Node_Type.VIDEO), toVideoTranslatable as (node: Node) => Translatable[]],
      ])
    )
    .get()
    .flat();

const nodeContainerDataTranslatables = (nodes: Node[]): NonTextualTranslatable[] =>
  extract(nodes)
    .filter(node => 'containerData' in (getDataFieldValue(node) ?? {}))
    .map((node: Node) => {
      const pluginData = getDataFieldName(node) as DataFieldNamesWithContainerData;
      return [
        ...fieldsToTranslatables(node as NonTextualNode, [
          pluginData,
          'containerData',
          'spoiler',
          'buttonText',
        ]),
        ...fieldsToTranslatables(node as NonTextualNode, [
          pluginData,
          'containerData',
          'spoiler',
          'description',
        ]),
      ];
    })
    .get()
    .flat();

const getTextualContent = (node: TextualNode): TextualTranslatable[] => {
  const { id, type } = node;
  const textNodes = extract(node)
    .filter(({ nodes }) => (nodes?.length ?? 0) > 0)
    .get();
  if (textNodes.length === 0) {
    return [];
  }
  return [
    {
      id,
      type,
      text: toHtml({
        nodes: textNodes,
      }),
    },
  ];
};
