import { identity } from 'fp-ts-esm/function';
import { not } from 'fp-ts-esm/Predicate';
import type { Attribute, Element } from 'parse5';

import { and, or } from './../../../../index.js';

import { partitionBy } from '../../../node-utils.js';
import type { ContentNode } from '../core/models.js';
import type { AstRule } from '../core/parse5-utils.js';
import { appendChild, hasChild, hasClass, hasTag, isRoot, isText } from '../core/parse5-utils.js';

export const addParagraph =
  (parentNode: Element, attrs: Attribute[] = []) =>
  (): ContentNode => ({
    nodeName: 'p',
    tagName: 'p',
    childNodes: [],
    parentNode,
    attrs: parentNode.attrs ? parentNode.attrs.concat(attrs) : attrs,
    namespaceURI: parentNode.namespaceURI,
  });

export const rootTextToP: AstRule = [
  // @ts-ignore $TSFixMe
  and([isRoot, or([hasChild(isText), hasChild(hasTag('a'))])]),
  // @ts-ignore $TSFixMe
  (node: Element) => ({
    ...node,
    childNodes: partitionBy<ContentNode>(
      // @ts-ignore $TSFixMe
      and([not(isText), not(hasTag('a')), not(hasClass(c => c === 'root-text-anchor'))]),
      // @ts-ignore $TSFixMe
      and([hasTag('p'), hasClass(c => c === 'root-text-anchor')]),
      identity,
      addParagraph(node, [{ name: 'class', value: 'root-text-anchor' }]),
      // @ts-ignore $TSFixMe
      appendChild
    )(node.childNodes),
  }),
];
