import * as A from 'fp-ts-esm/Array';
import { flow, pipe } from 'fp-ts-esm/function';
import type { DocumentFragment } from 'parse5';

import type { ContentNode } from './models.js';
import type { AstRule } from './parse5-utils.js';
import { getChildNodes, toDocumentFragment } from './parse5-utils.js';

const applyRootRule =
  (rule: AstRule) =>
  (node: DocumentFragment): ContentNode => {
    const [_if, then] = rule;
    return _if(node as ContentNode) ? then(node as ContentNode) : (node as ContentNode);
  };

const applyRule =
  (rule: AstRule) =>
  (node: ContentNode): ContentNode => {
    const [_if, then] = rule;
    const processed = _if(node) ? then(node) : node;
    return {
      ...processed,
      childNodes: visit(rule)(processed),
    };
  };

const visit =
  (rule: AstRule) =>
  (element: ContentNode | DocumentFragment): ContentNode[] =>
    // @ts-ignore $TSFixMe
    pipe(element, getChildNodes, A.map(applyRule(rule)));

export const traverse = (rule: AstRule) => flow(visit(rule), toDocumentFragment);

export const traverseRoot = (rule: AstRule) => (root: DocumentFragment) =>
  pipe(root, applyRootRule(rule));
