import * as A from 'fp-ts-esm/Array';
import { flow, identity, pipe } from 'fp-ts-esm/function';
import * as O from 'fp-ts-esm/Option';
import { not } from 'fp-ts-esm/Predicate';
import * as RONEA from 'fp-ts-esm/ReadonlyNonEmptyArray';
import * as R from 'fp-ts-esm/Record';
import * as S from 'fp-ts-esm/string';
import type { Element } from 'parse5';

import type { Node, PluginContainerData, TextStyle, TextStyle_TextAlignment } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type, Node_Type, PluginContainerData_Alignment } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { and, or } from '../../../../fp-utils.js';
import {
  createCaptionNode,
  createLink,
  createNode,
  createParagraphNode,
  createTableCellNode,
  createTableNode,
  createTableRowNode,
  createTextNode,
} from '../../../node-utils.js';
import type { Rule } from '../core/models.js';
import {
  getAttributes,
  getClassNames,
  getStyle,
  hasChild,
  hasParent,
  hasStyleFor,
  hasStyleRule,
  hasTag,
  isRoot,
  isText,
  isWhitespace,
  oneOf,
} from '../core/parse5-utils.js';
import type { Interceptor } from '../core/parser.js';
import { parser } from '../core/parser.js';
import {
  backgroundStyleToTextHighlight,
  colorStyleToTextColor,
  hToHeading,
  identityRule,
  imgToImage,
  lToList,
  pToParagraph,
  textToText,
} from '../core/rules.js';
import { aToCustomLink } from './a-to-custom-link.js';
import { iframeToVimeoVideo, iframeToYoutubeVideo } from './iframe-to-video.js';
import { postprocess } from './postprocess.js';
import { preprocess } from './preprocess.js';

const noEmptyLineText: Rule = [
  // @ts-ignore $TSFixMe
  and([isText, not(isWhitespace), not(hasParent(isRoot))]),
  textToText[1],
];

// TODO: remove direct nodeUtils usage
const rootTextToP: Rule = [
  // @ts-ignore $TSFixMe
  and([isText, hasParent(isRoot)]),
  ctx => el => [createParagraphNode(textToText[1](ctx)(el))],
];

const traverseDiv: Rule = [hasTag('div'), identityRule[1]];

const traverseSpan: Rule = [
  and([
    // @ts-ignore $TSFixMe
    hasTag('span'),
    // @ts-ignore $TSFixMe
    not(hasStyleFor('font-weight')),
    // @ts-ignore $TSFixMe
    not(hasStyleFor('font-style')),
    // @ts-ignore $TSFixMe
    not(hasStyleFor('text-decoration')),
    // @ts-ignore $TSFixMe
    not(hasStyleFor('color')),
    // @ts-ignore $TSFixMe
    not(hasStyleFor('background-color')),
    // @ts-ignore $TSFixMe
    not(hasStyleFor('vertical-align')),
  ]),
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    const processedImageNodes = processImageNode(context, element);
    return processedImageNodes.length > 0 ? processedImageNodes : identityRule[1](context)(element);
  },
];

const fontStyleToItalic: Rule = [
  // @ts-ignore $TSFixMe
  or([hasTag('em'), and([hasTag('span'), hasStyleRule({ 'font-style': 'italic' })])]),
  ({ addDecoration }) =>
    // @ts-ignore $TSFixMe
    (el: Element) =>
      addDecoration(Decoration_Type.ITALIC, {}, el),
];

const boldToTextDecoration: Rule = [
  // @ts-ignore $TSFixMe
  oneOf(['b', 'strong']),
  ({ addDecoration }) =>
    // @ts-ignore $TSFixMe
    (el: Element) =>
      addDecoration(Decoration_Type.BOLD, {}, el),
];

const fontWeightToDecoration: Rule = [
  // @ts-ignore $TSFixMe
  and([hasTag('span'), hasStyleFor('font-weight')]),
  ({ addDecoration, visit }) =>
    // @ts-ignore $TSFixMe
    (el: Element) => {
      const fontWeight = pipe(
        getStyle(el),
        O.chain(R.lookup('font-weight')),
        O.fold(() => '', identity)
      );
      if (fontWeight === 'bold' || parseInt(fontWeight, 10) >= 700) {
        return addDecoration(Decoration_Type.BOLD, {}, el);
      }
      return visit(el);
    },
];

const textDecorationToUnderline: Rule = [
  // @ts-ignore $TSFixMe
  or([hasTag('u'), and([hasTag('span'), hasStyleRule({ 'text-decoration': 'underline' })])]),
  ({ addDecoration }) =>
    // @ts-ignore $TSFixMe
    (el: Element) =>
      addDecoration(Decoration_Type.UNDERLINE, {}, el),
];

const linethroughToStrikethrough: Rule = [
  or([
    // @ts-ignore $TSFixMe
    oneOf(['s', 'del', 'strike']),
    // @ts-ignore $TSFixMe
    and([hasTag('span'), hasStyleRule({ 'text-decoration': 'line-through' })]),
  ]),
  ({ addDecoration }) =>
    // @ts-ignore $TSFixMe
    (el: Element) =>
      addDecoration(Decoration_Type.STRIKETHROUGH, {}, el),
];

const textToSuperscript: Rule = [
  // @ts-ignore $TSFixMe
  or([oneOf(['sup']), and([hasTag('span'), hasStyleRule({ 'vertical-align': 'super' })])]),
  ({ addDecoration }) =>
    // @ts-ignore $TSFixMe
    (el: Element) =>
      addDecoration(Decoration_Type.SUPERSCRIPT, { superscriptData: true }, el),
];

const textToSubscript: Rule = [
  // @ts-ignore $TSFixMe
  or([oneOf(['sub']), and([hasTag('span'), hasStyleRule({ 'vertical-align': 'sub' })])]),
  ({ addDecoration }) =>
    // @ts-ignore $TSFixMe
    (el: Element) =>
      addDecoration(Decoration_Type.SUBSCRIPT, { subscriptData: true }, el),
];

type Alignment = 'LEFT' | 'RIGHT' | 'CENTER' | '';

const alignmentToTextStyle = (alignment: Alignment): Partial<TextStyle> => ({
  textAlignment: alignment as TextStyle_TextAlignment,
});

const alignmentToContainerData = (align: Alignment) => ({
  alignment: align as PluginContainerData_Alignment,
});

const getAlignment = flow(
  RONEA.filter((c: string) => ['align-left', 'align-right', 'align-center'].includes(c)),
  O.map(RONEA.head),
  O.map(S.replace('align-', '')),
  O.fold(() => '', S.toUpperCase)
);

const getAlignmentByClass = flow(getClassNames, getAlignment);
const hasAlignmentClass = flow(getAlignmentByClass, Boolean);

const mergeWithTextStyle =
  (dataProp: 'paragraphData' | 'headingData', textStyle: Partial<TextStyle>) => (node: Node) => ({
    ...node,
    [dataProp]: {
      ...node[dataProp],
      textStyle: { ...node[dataProp]?.textStyle, ...textStyle },
    },
  });

const mergeWithContainerData =
  (dataProp: 'imageData' | 'videoData', containerData: PluginContainerData) => (node: Node) => ({
    ...node,
    [dataProp]: {
      ...node[dataProp],
      containerData: {
        ...node[dataProp]?.containerData,
        ...containerData,
      },
    },
  });

const lineHeightToTextStyle = (lineHeight?: string): Partial<TextStyle> => ({ lineHeight });

const getLineHeight = flow(
  getStyle,
  O.chain(R.lookup('line-height')),
  O.fold(() => '', identity)
);

const figureToMedia: Rule = [
  hasTag('figure'),
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    const result = context.visit(element);
    const mediaNode = result.find(node =>
      [Node_Type.IMAGE, Node_Type.VIDEO, Node_Type.GIF].includes(node.type)
    );
    const figCaptionNode = result.find(node => node.type === Node_Type.CAPTION);
    if (mediaNode) {
      return [
        {
          ...mediaNode,
          ...(figCaptionNode ? { nodes: [...mediaNode.nodes, figCaptionNode] } : {}),
        },
      ];
    } else {
      return [];
    }
  },
];

const figCaptionToCaption: Rule = [
  hasTag('figcaption'),
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    const node = context.visit(element);

    const findChildTextNode = (nodes: Node[]): Node | undefined => {
      for (const n of nodes) {
        if (n.type === Node_Type.TEXT) {
          return n;
        }
        if (n.nodes && n.nodes.length > 0) {
          const childTextNode = findChildTextNode(n.nodes);
          if (childTextNode) {
            return childTextNode;
          }
        }
      }
      return undefined;
    };

    const textNode = findChildTextNode(node);
    return textNode ? [createCaptionNode([textNode])] : [];
  },
];

const pWitTextToStyledParagraph: Rule = [
  // @ts-ignore $TSFixMe
  and([pToParagraph[0], hasChild(not(isWhitespace))]),
  // @ts-ignore $TSFixMe
  context => (element: Element) =>
    pipe(
      element,
      pToParagraph[1](context),
      A.map(
        hasAlignmentClass(element)
          ? mergeWithTextStyle(
              'paragraphData',
              // @ts-ignore $TSFixMe
              pipe(element, getAlignmentByClass, alignmentToTextStyle)
            )
          : identity
      ),
      A.map(
        hasStyleFor('line-height')(element)
          ? mergeWithTextStyle('paragraphData', pipe(element, getLineHeight, lineHeightToTextStyle))
          : identity
      )
    ),
];

const hToStyledHeading: Rule = [
  hToHeading[0],
  // @ts-ignore $TSFixMe
  context => (element: Element) =>
    pipe(
      element,
      hToHeading[1](context),
      A.map(
        hasAlignmentClass(element)
          ? mergeWithTextStyle(
              'headingData',
              // @ts-ignore $TSFixMe
              pipe(element, getAlignmentByClass, alignmentToTextStyle)
            )
          : identity
      ),
      A.map(
        hasStyleFor('line-height')(element)
          ? mergeWithTextStyle('headingData', pipe(element, getLineHeight, lineHeightToTextStyle))
          : identity
      )
    ),
];

const iframeToAlignedVimeoVideo: Rule = [
  iframeToVimeoVideo[0],
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    return pipe(
      element,
      iframeToVimeoVideo[1](context),
      A.map(
        hasAlignmentClass(element)
          ? mergeWithContainerData(
              'videoData',
              // @ts-ignore $TSFixMe
              pipe(element, getAlignmentByClass, alignmentToContainerData)
            )
          : identity
      )
    );
  },
];

const iframeToAlignedYoutubeVideo: Rule = [
  iframeToYoutubeVideo[0],
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    return pipe(
      element,
      iframeToYoutubeVideo[1](context),
      A.map(
        hasAlignmentClass(element)
          ? mergeWithContainerData(
              'videoData',
              // @ts-ignore $TSFixMe
              pipe(element, getAlignmentByClass, alignmentToContainerData)
            )
          : identity
      )
    );
  },
];

const videoToVideo: Rule = [
  hasTag('video'),
  // @ts-ignore $TSFixMe
  () => (element: Element) => {
    const attrs = getAttributes(element);
    return [
      createNode(Node_Type.VIDEO, {
        nodes: [],
        data: {
          video: {
            src: { url: attrs.src },
          },
        },
      }),
    ];
  },
];

const imgToAlignedImage: Rule = [
  imgToImage[0],
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    return pipe(
      element,
      imgToImage[1](context),
      A.map(
        hasAlignmentClass(element)
          ? mergeWithContainerData(
              'imageData',
              // @ts-ignore $TSFixMe
              pipe(element, getAlignmentByClass, alignmentToContainerData)
            )
          : mergeWithContainerData('imageData', {
              alignment: PluginContainerData_Alignment.CENTER,
            })
      )
    );
  },
];

const KNOWN_TAGS = [
  'p',
  'div',
  'span',
  'figure',
  'img',
  'a',
  's',
  'strike',
  'del',
  'iframe',
  'strong',
  'em',
  'u',
  'ol',
  'ul',
  'li',
  'b',
  'i',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'table',
  'thead',
  'tbody',
  'tfoot',
  'tr',
  'th',
  'td',
  'sup',
  'sub',
  'figcaption',
];

const unwrapUnknownTag: Rule = [
  node => {
    return !KNOWN_TAGS.includes(node.nodeName.toLowerCase());
  },
  identityRule[1],
];

const processImageNode = (context: any, element: Element) => {
  const anchorNode = element.childNodes.find((node: $TSFixMe) => node.nodeName === 'a') as
    | Element
    | undefined;

  if (anchorNode) {
    const imageNode = anchorNode.childNodes.find((node: $TSFixMe) => node.nodeName === 'img') as
      | Element
      | undefined;
    if (imageNode) {
      const imageNodes = imgToAlignedImage[1](context)(imageNode);
      const linkAttrs = getAttributes(anchorNode);
      const linkData = linkAttrs.href
        ? {
            link: createLink({ ...linkAttrs, url: linkAttrs.href }),
          }
        : undefined;

      return imageNodes.map(imgNode => ({
        ...imgNode,
        imageData: {
          ...imgNode.imageData,
          link: linkData?.link,
        },
      }));
    }
  }

  const directImageNode = element.childNodes.find((node: $TSFixMe) => node.nodeName === 'img') as
    | Element
    | undefined;

  if (directImageNode) {
    return imgToImage[1](context)(directImageNode);
  }

  return [];
};

const tableToTable: Rule = [
  hasTag('table'),
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    const header = element.childNodes.find((node: $TSFixMe) => node.nodeName === 'thead');

    const hasColumnHeader = (node: Element): boolean => {
      if (node.nodeName === 'tr') {
        if (
          !node.childNodes ||
          node.childNodes.length === 0 ||
          node.childNodes[0].nodeName !== 'th'
        ) {
          return false;
        }
      }
      if (node.childNodes && node.childNodes.length > 0) {
        for (const childNode of node.childNodes) {
          if (!hasColumnHeader(childNode as Element)) {
            return false;
          }
        }
      }
      return true;
    };
    return [
      createTableNode(context.visit(element), {
        rowHeader: !!header,
        columnHeader: hasColumnHeader(element),
        cellPadding: [],
      }),
    ];
  },
];

const omitTableWrappers: Rule = [
  // @ts-ignore $TSFixMe
  or([hasTag('thead'), hasTag('tbody'), hasTag('tfoot')]),
  // @ts-ignore $TSFixMe
  context => (element: Element) => context.visit(element),
];

const trToRow: Rule = [
  hasTag('tr'),
  // @ts-ignore $TSFixMe
  context => (element: Element) => [createTableRowNode(context.visit(element))],
];

const tdToCell: Rule = [
  // @ts-ignore $TSFixMe
  or([hasTag('td'), hasTag('th')]),
  // @ts-ignore $TSFixMe
  context => (element: Element) => {
    let childParagraph: Node | undefined;
    if (element.childNodes.length === 0) {
      childParagraph = createParagraphNode();
    } else {
      const textChild = element.childNodes.find(isText);
      if (textChild) {
        childParagraph = createParagraphNode([
          createTextNode(textChild.value, context.decorations),
        ]);
      }
    }

    return [createTableCellNode(childParagraph ? [childParagraph] : context.visit(element))];
  },
];

export const fromCKEditorHtml = (s: string, interceptorFn: Interceptor = ({ result }) => result) =>
  flow(
    () => preprocess(s),
    parser(
      [
        tableToTable,
        omitTableWrappers,
        tdToCell,
        trToRow,
        noEmptyLineText,
        rootTextToP,
        pWitTextToStyledParagraph,
        lToList,
        hToStyledHeading,
        aToCustomLink,
        boldToTextDecoration,
        fontWeightToDecoration,
        fontStyleToItalic,
        colorStyleToTextColor,
        backgroundStyleToTextHighlight,
        textDecorationToUnderline,
        iframeToAlignedYoutubeVideo,
        iframeToAlignedVimeoVideo,
        imgToAlignedImage,
        traverseDiv,
        traverseSpan,
        figureToMedia,
        unwrapUnknownTag,
        linethroughToStrikethrough,
        textToSuperscript,
        textToSubscript,
        videoToVideo,
        figCaptionToCaption,
      ],
      interceptorFn
    ),
    postprocess
  )();
