import * as A from 'fp-ts-esm/Array';
import * as E from 'fp-ts-esm/Either';
import { flow, pipe } from 'fp-ts-esm/function';
import * as M from 'fp-ts-esm/Monoid';
import * as O from 'fp-ts-esm/Option';
import * as S from 'fp-ts-esm/string';
import { encode } from 'html-entities';

import type { Decoration, Node, RichContent, TextData, TextStyle } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type, Link_Target, Node_Type, TextStyle_TextAlignment } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosPalette } from './../../../../ricos-types/index.js';
import { CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE } from './../../../../_shared/list-checkbox/checkbox-list-style.js';
import { resolveDocumentColorToCss, resolveDocumentColorToHex } from './../../../../_shared/theme-color-token.js';
import { unreachable } from './../../../../_shared/uncreachable.js';

import { firstRight } from '../../../fp-utils.js';

const compact = <T>(arr: readonly T[]): NonNullable<T>[] =>
  arr.filter((item): item is NonNullable<T> => !!item);

const pickTruthy = <T extends Record<string, unknown>>(obj: T): Partial<T> =>
  Object.fromEntries(Object.entries(obj).filter(([, value]) => !!value)) as Partial<T>;

export type Interceptor = (context: { node: Node; result: string | string[] }) => string | string[];

export const toHtml = (
  content: RichContent | Node[],
  interceptorFn: Interceptor = ({ result }) => result,
  separator = '\n',
  palette?: RicosPalette
): string => {
  const nodes = Array.isArray(content) ? content : (content.nodes ?? []);
  return `${nodeArrayToHtml(nodes, interceptorFn, separator, palette)}`;
};

export const ensureNodeType = (nodes: Node[]): Node[] =>
  nodes.map(node => {
    node.type = node.type || Node_Type.PARAGRAPH;
    ensureNodeType(node.nodes || []);
    return node;
  });

const nodeArrayToHtml = (
  nodes: Node[],
  interceptorFn: Interceptor,
  separator = '',
  palette?: RicosPalette
): string => {
  const nodesWithTypes = ensureNodeType(nodes);
  return nodesWithTypes
    .flatMap(node => {
      const result = nodeToHtml(node, interceptorFn, palette);
      return interceptorFn({ node, result });
    })
    .join(separator);
};

const nodeToHtml = (
  node: Node,
  interceptorFn: Interceptor,
  palette?: RicosPalette
): string | string[] => {
  if (node.type === Node_Type.TEXT && node.textData) {
    return decorateTextElement({ ...node.textData, text: encode(node.textData.text) }, palette);
  }
  if (node.type === Node_Type.PARAGRAPH && node.nodes?.length === 0) {
    return EMPTY_PARAGRAPH;
  }

  let tag: NodeHtmlTag = NODE_TO_HTML_TAG[node.type as keyof typeof NODE_TO_HTML_TAG];
  if (node.type === Node_Type.HEADING && node.headingData) {
    const { level } = node.headingData;
    tag = `h${level}` as NodeHtmlTag;
  }

  if (node.type === Node_Type.PARAGRAPH && node.paragraphData) {
    const children = nodeArrayToHtml(node.nodes ?? [], interceptorFn, undefined, palette);
    const attrs = createTextStyleAttrs(node.paragraphData.textStyle);
    return createHtmlTag(tag, children, attrs);
  }

  if (node.type === Node_Type.LAYOUT) {
    return nodeArrayToHtml(
      node.nodes?.map(cell => cell.nodes)?.flat() ?? [],
      interceptorFn,
      undefined,
      palette
    );
  }

  if (tag) {
    const children = nodeArrayToHtml(node.nodes ?? [], interceptorFn, undefined, palette);
    return createHtmlTag(tag, children, createNodeAttrs(node));
  }
  return [];
};

const createLinkAttrs = (decoration: Decoration): Record<string, string> => {
  const rel = Object.entries(decoration.linkData?.link?.rel || {})
    .filter(([_, value]) => !!value)
    .map(([key]) => key)
    .join(' ');
  const targetRaw = decoration.linkData?.link?.target;
  const ignoreTarget = [undefined, Link_Target.UNRECOGNIZED, Link_Target.SELF].includes(targetRaw);
  const target = ignoreTarget ? '' : `_${targetRaw?.toLowerCase()}`;
  const anchor = decoration.linkData?.link?.anchor || '';
  const href = decoration.linkData?.link?.url || '';
  return pickTruthy({ href, rel, anchor, target });
};

const createAnchorAttrs = (decoration: Decoration): Record<string, string> => {
  const anchor = decoration.anchorData?.anchor || '';
  return { href: `#${anchor}`, rel: 'noopener noreferrer' };
};

// NOTE: Mention's HTML representation is not interactive. Might be fixed in the future
const createMentionAttrs = (decoration: Decoration): Record<string, string> => {
  const { name = '', slug = '', id = '' } = decoration.mentionData || {};
  if (!name && !slug && !id) {
    return {};
  }
  return pickTruthy({
    role: 'link',
    'data-mention-name': name,
    'data-mention-slug': slug,
    'data-mention-id': id,
  });
};

// NOTE: Spoiler's HTML representation is not interactive. Might be fixed in the future
const createSpoilerAttrs = () => ({ 'data-spoiler': 'true' });

const createColorAttrs = (decoration: Decoration, palette?: RicosPalette) => {
  const { foreground, background } = decoration.colorData || {};
  const resolveColor = (color?: string) =>
    palette ? resolveDocumentColorToHex(color, palette) : resolveDocumentColorToCss(color);
  const fg = resolveColor(foreground);
  const bg = resolveColor(background);
  const style = pipe(
    [fg && `color: ${fg};`, bg && `background-color: ${bg};`],
    compact,
    M.concatAll(S.Monoid)
  );
  return pickTruthy({ style });
};

const createTextStyleAttrs = (textStyle?: TextStyle) => {
  const { textAlignment } = textStyle || {};
  const textAlign = normalizeTextAlignment(textAlignment);
  const style = pipe([textAlign && `text-align: ${textAlign};`], compact, M.concatAll(S.Monoid));
  return pickTruthy({ style });
};

const createNodeAttrs = (node: Node): Record<string, string> => {
  if (node.type === Node_Type.CHECKBOX_LIST) {
    return { 'data-list-style': CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE };
  }

  if (node.type === Node_Type.LIST_ITEM && node.listItemData?.checked !== undefined) {
    return { role: 'checkbox', 'aria-checked': node.listItemData.checked ? 'true' : 'false' };
  }

  return {};
};

const isType = (type: Decoration_Type) => (decoration: Decoration) => decoration.type === type;

const createHtmlAttrs = (decoration: Decoration, palette?: RicosPalette): Record<string, string> =>
  firstRight(decoration, {}, [
    [isType(Decoration_Type.LINK), createLinkAttrs],
    [isType(Decoration_Type.ANCHOR), createAnchorAttrs],
    [isType(Decoration_Type.MENTION), createMentionAttrs],
    [isType(Decoration_Type.SPOILER), createSpoilerAttrs],
    [isType(Decoration_Type.COLOR), decoration => createColorAttrs(decoration, palette)],
  ]);

const createHtmlTag = (
  tag: NodeHtmlTag | DecorationHtmlTag,
  child: string,
  attrs: Record<string, string> = {}
): string => {
  const isFragment = tag === 'fragment';
  const prefix = tag === 'li' ? '\n  ' : '';
  const suffix = ['ul', 'ol'].includes(tag) ? '\n' : '';
  return isFragment
    ? `${child}${suffix}`
    : `${prefix}<${tag}${attrsToString(attrs)}>${child}${suffix}</${tag}>`;
};

const attrsToString = (attrs: Record<string, string>): string =>
  Object.entries(attrs)
    .map(([key, value]) => ` ${key}="${value}"`)
    .join('');

const toForegroundDecoration = (d: Decoration): O.Option<Decoration> =>
  d.colorData?.foreground
    ? O.some({ type: Decoration_Type.COLOR, colorData: { foreground: d.colorData.foreground } })
    : O.none;

const toBackgroundDecoration = (d: Decoration): O.Option<Decoration> =>
  d.colorData?.background
    ? O.some({ type: Decoration_Type.COLOR, colorData: { background: d.colorData.background } })
    : O.none;

const expandColorDecoration = (decoration: Decoration): Decoration[] =>
  pipe([toBackgroundDecoration, toForegroundDecoration], A.ap(A.of(decoration)), A.compact);

const eitherColorDecoration = (d: Decoration): E.Either<Decoration, Decoration> =>
  d.type === Decoration_Type.COLOR ? E.right(d) : E.left(d);

const ensureDecorations = (decorations?: Decoration[]) => decorations || [];

const normalizeDecorations: (decorations: Decoration[] | undefined) => Decoration[] = flow(
  ensureDecorations,
  A.map(flow(eitherColorDecoration, E.fold(A.of, expandColorDecoration))),
  A.flatten
);

const normalizeTextAlignment = (textAlignment?: TextStyle_TextAlignment) => {
  switch (textAlignment) {
    case TextStyle_TextAlignment.CENTER:
    case TextStyle_TextAlignment.JUSTIFY:
    case TextStyle_TextAlignment.LEFT:
    case TextStyle_TextAlignment.RIGHT:
      return textAlignment.toLowerCase();
    case TextStyle_TextAlignment.AUTO:
    case TextStyle_TextAlignment.UNRECOGNIZED:
    case undefined:
      return undefined;
    default:
      throw unreachable(textAlignment);
  }
};

const decorateTextElement = ({ text, decorations }: TextData, palette?: RicosPalette): string => {
  const normalizedDecorations = normalizeDecorations(decorations);
  return normalizedDecorations.reduce((child, decoration) => {
    const tag: DecorationHtmlTag =
      DECORATION_TO_HTML_TAG[decoration.type as keyof typeof DECORATION_TO_HTML_TAG];
    return tag ? createHtmlTag(tag, child, createHtmlAttrs(decoration, palette)) : child;
  }, text);
};

type DecorationHtmlTag = (typeof DECORATION_TO_HTML_TAG)[keyof typeof DECORATION_TO_HTML_TAG];

const DECORATION_TO_HTML_TAG = {
  [Decoration_Type.COLOR]: 'span',
  [Decoration_Type.MENTION]: 'span',
  [Decoration_Type.SPOILER]: 'span',
  [Decoration_Type.BOLD]: 'strong',
  [Decoration_Type.ITALIC]: 'em',
  [Decoration_Type.UNDERLINE]: 'u',
  [Decoration_Type.LINK]: 'a',
  [Decoration_Type.ANCHOR]: 'a',
  [Decoration_Type.STRIKETHROUGH]: 's',
} as const;

type NodeHtmlTag =
  | (typeof NODE_TO_HTML_TAG)[keyof typeof NODE_TO_HTML_TAG]
  | 'h1'
  | 'h2'
  | 'h3'
  | 'h4'
  | 'h5'
  | 'h5';

const NODE_TO_HTML_TAG = {
  [Node_Type.BULLETED_LIST]: 'ul',
  [Node_Type.CHECKBOX_LIST]: 'ul',
  [Node_Type.COLLAPSIBLE_LIST]: 'ul',
  [Node_Type.ORDERED_LIST]: 'ol',
  [Node_Type.LIST_ITEM]: 'li',
  [Node_Type.COLLAPSIBLE_ITEM]: 'li',
  [Node_Type.COLLAPSIBLE_ITEM_TITLE]: 'fragment',
  [Node_Type.COLLAPSIBLE_ITEM_BODY]: 'fragment',
  [Node_Type.PARAGRAPH]: 'p',
} as const;

const EMPTY_PARAGRAPH = '<p><br /></p>';
