import * as E from 'fp-ts-esm/Either';
import { flow, identity, pipe } from 'fp-ts-esm/function';
import { not } from 'fp-ts-esm/Predicate';
import * as S from 'fp-ts-esm/string';
import type { Element } from 'parse5';

import type { Link } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { and, getMatches } from '../../../../fp-utils.js';
import { createLink } from '../../../node-utils.js';
import type { ContentNode, Rule } from '../core/models.js';
import { getAttributes, hasParent, isRoot } from '../core/parse5-utils.js';
import { aToLink } from '../core/rules.js';

const parseNavigationData = flow(
  S.replace(/~#~/g, '"'),
  d =>
    E.tryCatch(
      () => JSON.parse(d),
      () => ({ type: 'pageLink', id: d })
    ),
  E.fold(identity, identity)
);

const toCustomData = flow(
  getMatches(/Wix\.(.+)\('(.+)'\)/),
  E.fromOption(() => 'failed to parse custom link onclick'),
  E.map(([, , data]: string[]) => parseNavigationData(data)),
  E.map(JSON.stringify),
  E.fold(identity, identity)
);

const getData = (onclick?: string): Record<string, string> =>
  onclick?.startsWith('Wix.') ? { customData: toCustomData(onclick) } : {};

const mergeData =
  (onclick?: string) =>
  (link: Link): Link => ({ ...link, ...getData(onclick) });

const createCustomLink = ({ url, onclick, ...rest }: Record<string, string>): Link =>
  pipe({ url, ...rest }, createLink, mergeData(onclick));

export const aToCustomLink: Rule = [
  and([
    aToLink[0] as (data: unknown) => boolean,
    not(hasParent(isRoot)) as (data: unknown) => boolean,
  ]),
  context => (node: ContentNode) => {
    const attrs = getAttributes(node as Element);
    return context.addDecoration(
      Decoration_Type.LINK,
      { linkData: { link: createCustomLink({ ...attrs, url: attrs.href }) } },
      node as Element
    );
  },
];
