import * as A from 'fp-ts-esm/Array';
import * as E from 'fp-ts-esm/Either';
import { flow, identity, pipe } from 'fp-ts-esm/function';

import type { Node, RichContent } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { extract } from '../../../../RicosContentAPI/extract.js';
import { modify } from '../../../../RicosContentAPI/modify.js';
import { createNode, createParagraphNode, partitionBy } from '../../../node-utils.js';

// scapegoat
const decomposeListItem = (node: Node): Node[] =>
  partitionBy<Node>(
    ({ type }) =>
      ![
        Node_Type.PARAGRAPH,
        Node_Type.ORDERED_LIST,
        Node_Type.BULLETED_LIST,
        Node_Type.CHECKBOX_LIST,
      ].includes(type), // anything but paragraph or list is a separator
    ({ type }) => type === Node_Type.BULLETED_LIST, // partition is a bullet list
    identity, // separator added as is
    () =>
      createNode(Node_Type.BULLETED_LIST, {
        nodes: [createNode(Node_Type.LIST_ITEM, { nodes: [], data: {} })],
        data: {},
      }), // partition initialization
    (list, paragraphOrList) => list.nodes?.[0]?.nodes?.push(paragraphOrList)
  )(node.nodes?.[0]?.nodes || []);

// decompose list items resulted by splitUnsupportedLists
const decomposeUnsupportedListItems = (content: RichContent): RichContent =>
  modify(content)
    .filter(({ type }) => type === Node_Type.ORDERED_LIST)
    .filter(
      ({ nodes }) =>
        Number(
          (nodes?.length === 1 &&
            nodes?.[0]?.nodes?.filter(
              ({ type }) =>
                ![
                  Node_Type.PARAGRAPH,
                  Node_Type.ORDERED_LIST,
                  Node_Type.BULLETED_LIST,
                  Node_Type.CHECKBOX_LIST,
                ].includes(type)
            )?.length) ??
            0
        ) > 0
    )
    .set(decomposeListItem);

// segregat oves ab haedis
const splitList = (list: Node): Node[] =>
  partitionBy<Node>(
    li =>
      (li.nodes?.filter(
        ({ type }) =>
          ![
            Node_Type.PARAGRAPH,
            Node_Type.ORDERED_LIST,
            Node_Type.BULLETED_LIST,
            Node_Type.CHECKBOX_LIST,
          ].includes(type)
      )?.length ?? 0) > 0, // separator is a list item with unsupported nodes
    n => n.type === Node_Type.BULLETED_LIST, // partition is an empty bullet list
    n => createNode(Node_Type.ORDERED_LIST, { nodes: [n], data: {} }), // separator list item wrapped with ordered list
    () => createNode(Node_Type.BULLETED_LIST, { nodes: [], data: {} }), // new partition
    (list, item) => list.nodes?.push(item) // add valid list item to partition
  )(list.nodes ?? []);

// find lists whose items contain some non-paragraphs or non-lists
const getListToSplitIds = (content: RichContent): string[] =>
  extract(content?.nodes ?? [])
    .filter(
      ({ type }) =>
        type === Node_Type.BULLETED_LIST ||
        type === Node_Type.CHECKBOX_LIST ||
        type === Node_Type.ORDERED_LIST
    )
    .map(({ id, nodes }) => ({ id, nodes: (nodes ?? []).flatMap(n => n.nodes ?? []) }))
    .filter(
      ({ nodes }) =>
        nodes.filter(
          ({ type }) =>
            ![
              Node_Type.PARAGRAPH,
              Node_Type.ORDERED_LIST,
              Node_Type.BULLETED_LIST,
              Node_Type.CHECKBOX_LIST,
            ].includes(type)
        ).length > 0
    )
    .map(({ id }) => id)
    .get();

// separate legit draft list items from unsupported ones (containing anything except paragraphs and nested lists)
const splitUnsupportedLists = (content: RichContent): E.Either<RichContent, RichContent> => {
  const listToSplitIds = getListToSplitIds(content);
  // Either used for short-circuiting of decomposeUnsupportedListItems, if nothing was splitted
  return listToSplitIds.length > 0
    ? E.right(
        modify(content)
          .filter(({ id }) => listToSplitIds.includes(id))
          .set(splitList)
      )
    : E.left(content);
};

const newLineP: Node = {
  type: Node_Type.TEXT,
  id: '',
  nodes: [],
  textData: { text: '\n', decorations: [] },
};

const mergeAdjacentParagraphs = (listItem: Node): Node => ({
  ...listItem,
  nodes: partitionBy<Node>(
    ({ type }) => type !== Node_Type.PARAGRAPH, // any non-paragraph is separator
    ({ type }) => type === Node_Type.PARAGRAPH, // paragraph is partition
    identity, // seprator added as is to result partition array
    paragraph => ({ ...paragraph, nodes: [] }), // empty paragraph is a new partition
    // paragraph nodes appended to partition nodes, separated by \n
    (containerP, mergedP) =>
      (containerP.nodes = (containerP.nodes || [])
        .concat(containerP.nodes?.length ? [newLineP] : [])
        .concat(mergedP.nodes ?? []))
  )(listItem.nodes ?? []),
});

// merge any adjacent paragraphs into a single paragraph
const mergeListParagraphNodes = (content: RichContent): RichContent =>
  modify(content)
    .filter(({ type }) => type === Node_Type.LIST_ITEM)
    .filter(
      ({ nodes }) => (nodes?.filter(({ type }) => type === Node_Type.PARAGRAPH).length ?? 0) > 1
    )
    .set(mergeAdjacentParagraphs);

const wrapTopLevelTextInParagraphs = (content: RichContent): RichContent => {
  const nodes = pipe(
    content.nodes,
    A.map(node => {
      if (node.type === Node_Type.TEXT && node.textData?.text?.trim() !== '') {
        return createParagraphNode([node]);
      }
      return node;
    })
  );

  return {
    ...content,
    nodes,
  };
};

export const postprocess = flow(
  mergeListParagraphNodes,
  splitUnsupportedLists,
  E.map(decomposeUnsupportedListItems),
  E.fold(identity, identity),
  wrapTopLevelTextInParagraphs
);
