import type { Node } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { RichContent } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { createParagraphNode, createTextNode, initializeMetadata } from '../../node-utils.js';

export const fromPlainText = (text: string): RichContent => {
  const paragraphs = text
    .split('\n')
    .map(
      (paragraph: string): Node => createParagraphNode(paragraph ? [createTextNode(paragraph)] : [])
    );

  const content: RichContent = {
    nodes: paragraphs,
    metadata: initializeMetadata(),
  };

  return RichContent.fromJSON(content);
};
