import * as E from 'fp-ts-esm/Either';
import { flow, identity } from 'fp-ts-esm/function';
import * as S from 'fp-ts-esm/string';
import type { Element } from 'parse5';

import type { VideoData } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { and } from '../../../../fp-utils.js';
import { createNode } from '../../../node-utils.js';
import type { ContentNode, Rule } from '../core/models.js';
import { getAttributes, hasAttribute, hasTag } from '../core/parse5-utils.js';

const toURL = (str: string) =>
  E.tryCatch(
    () => new URL(str),
    () => 'invalid URL string'
  );

const getVideoId = (url: URL): E.Either<string, string> =>
  url.host.includes('youtube') && url.pathname.includes('/embed/')
    ? E.right(url.pathname.replace('/embed/', ''))
    : E.left('not a youtube source');

const toYoutubeUrl = flow(
  toURL,
  E.chain(getVideoId),
  E.fold(identity, id => `https://www.youtube.com/watch?v=${id}`)
);

const toVideoData = (urlResolver: (src: string) => string) =>
  flow(getAttributes, ({ src }) => ({ video: { src: { url: urlResolver(src) } } }) as VideoData);

export const iframeToYoutubeVideo: Rule = [
  and([hasTag('iframe') as any, hasAttribute('src', S.includes('youtube'))]),
  () => (node: ContentNode) => [
    createNode(Node_Type.VIDEO, {
      nodes: [],
      data: { ...toVideoData(toYoutubeUrl)(node as Element) },
    }),
  ],
];

const toVimeoSource = (url: URL): string =>
  url.host.includes('vimeo') ? url.toString() : 'unsupported video source';

const toVimeoUrl = flow(toURL, E.fold(identity, toVimeoSource));

export const iframeToVimeoVideo: Rule = [
  and([hasTag('iframe') as any, hasAttribute('src', S.includes('vimeo'))]),
  () => (node: ContentNode) => [
    createNode(Node_Type.VIDEO, {
      nodes: [],
      data: { ...toVideoData(toVimeoUrl)(node as Element) },
    }),
  ],
];
