import type { RichContent } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { getDefaultAudioUrl, getDefaultVideoUrl } from './convert-nodes.js';
import { toPlainTextBase } from './to-plain-text-base.js';

interface PlainTextOptions {
  urlShortener?: (url: string) => string;
  getVideoUrl?: (fileId: string) => string;
  getVideoEmbeddedUrl?: (url: string) => string;
  getAudioUrl?: (fileId: string) => string;
  getGifUrl?: (url: string) => string;
  addLinksToText?: boolean;
  delimiter?: string;
}

export const toPlainTextSync = (content: RichContent, options: PlainTextOptions = {}) => {
  const gen = toPlainTextBase(content, options.delimiter, options.addLinksToText);
  let next = gen.next();

  while (!next.done) {
    switch (next.value.command) {
      case 'getImageUrl': {
        const url = options.urlShortener
          ? options.urlShortener?.(next.value.data)
          : next.value.data;
        next = gen.next(url);
        break;
      }
      case 'getVideoUrl': {
        const url = options.getVideoUrl
          ? options.getVideoUrl(next.value.data)
          : getDefaultVideoUrl(next.value.data);
        next = gen.next(url);
        break;
      }
      case 'getVideoEmbeddedUrl': {
        const url = options.getVideoEmbeddedUrl
          ? options.getVideoEmbeddedUrl(next.value.data)
          : next.value.data;
        next = gen.next(url);
        break;
      }
      case 'getAudioUrl': {
        const url = options.getAudioUrl
          ? options.getAudioUrl(next.value.data)
          : getDefaultAudioUrl(next.value.data);
        next = gen.next(url);
        break;
      }
      case 'getGifUrl': {
        const url = options.getGifUrl ? options.getGifUrl(next.value.data) : next.value.data;
        next = gen.next(url);
        break;
      }
      default:
        return '';
    }
  }

  return next.value;
};
