import type { Node, RichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosDocument } from './../../ricos-schema/next-schema/index.js';

import type { DraftContent } from '../types/index.js';

export const isContentStateEmpty = (contentState: DraftContent): boolean => {
  const { blocks } = contentState;
  if (blocks.length === 0) {
    return true;
  }
  if (blocks.length > 1) {
    return false;
  }
  const firstBlock = blocks[0];
  const { text, type, depth } = firstBlock;
  return text === '' && type === 'unstyled' && depth === 0;
};

export const isRichContentEmpty = (contentState: RichContent | RicosDocument): boolean => {
  if (contentState.nodes?.length === 0) {
    return true;
  } else if ((contentState.nodes?.length ?? 0) > 1) {
    return false;
  } else {
    let firstNode = contentState.nodes?.[0] as Node;
    // Unwrap CARD wrapper node
    if (firstNode?.type === Node_Type.CARD) {
      if (firstNode.nodes?.length !== 1) {
        return false;
      }
      firstNode = firstNode.nodes[0] as Node;
    }
    const { nodes, type, paragraphData } = firstNode;
    return (
      nodes?.length === 0 &&
      (type === Node_Type.PARAGRAPH || type === Node_Type.HEADING) &&
      [undefined, 0].includes(paragraphData?.indentation)
    );
  }
};
