// TODO: purify this module
import type { Decoration, LinkData, MentionData } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { cloneDeep } from './../../../../_shared/clone-deep.js';
import { deepMerge } from './../../../../_shared/deep-merge.js';

import { parseLink } from '../../node-utils.js';
import { FROM_RICOS_DECORATION_TYPE, TO_RICOS_DECORATION_DATA_FIELD } from '../consts.js';

export const convertDecorationToDraftData = (decoration: Decoration) => {
  const { type } = decoration;
  const dataFieldName =
    TO_RICOS_DECORATION_DATA_FIELD[
      FROM_RICOS_DECORATION_TYPE[
        type as keyof typeof FROM_RICOS_DECORATION_TYPE
      ] as keyof typeof TO_RICOS_DECORATION_DATA_FIELD
    ];
  return convertDecorationDataToDraft(type, decoration[dataFieldName as keyof typeof decoration]);
};

export const convertDecorationDataToDraft = (decorationType: Decoration_Type, data: $TSFixMe) => {
  const converters = {
    [Decoration_Type.MENTION]: convertMentionData,
    [Decoration_Type.LINK]: convertLinkData,
  };
  if (decorationType in converters) {
    const convert = converters[decorationType as keyof typeof converters];
    const newData = cloneDeep(data);
    convert(newData);
    return newData;
  }
  return data;
};

const convertMentionData = (data: Partial<MentionData> & { mention: $TSFixMe }) => {
  data.mention = { slug: data.slug, name: data.name, id: data.id };
  delete data.name;
  delete data.slug;
  delete data.id;
};

const convertLinkData = (
  data: LinkData & {
    url?: string;
    target?: string;
    rel?: string;
    anchor?: string;
    customData?: string;
  }
) => {
  if (data.link) {
    const { url, target, anchor, rel, customData } = parseLink(data.link);
    data.url = url;
    if (target) {
      data.target = target;
    }
    if (rel) {
      data.rel = rel;
    }
    if (anchor) {
      data.anchor = anchor;
    }
    if (customData) {
      const customDataObj = parseLinkCustomData(customData);
      deepMerge(data, customDataObj);
    }
    delete data.link;
  }
};

const parseLinkCustomData = (customData: string) => {
  try {
    return { customData: JSON.parse(customData) };
  } catch {
    console.error('failed to parse customData', customData); // oxlint-disable-line
    return { customData };
  }
};
