/* oxlint-disable fp/no-delete */
import { getDataFieldValue } from './../../../TranslatableAPI/utils.js';
import type { Node } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import type { RicosEntityMap } from '../../../types/index.js';
import { ENTITY_DECORATION_TO_MUTABILITY, TO_RICOS_DECORATION_TYPE } from '../consts.js';
import { convertDecorationToDraftData } from './convert-draft-plugin-data.js';
import { createEntity } from './create-entity.js';
import type { DraftTypedDecoration } from './decoration-parsers.js';

export const createDecorationEntityData = (
  decoration: DraftTypedDecoration,
  entityKey: number
): RicosEntityMap => {
  const { type, emojiData } = decoration;

  const data =
    emojiData ||
    convertDecorationToDraftData({
      ...decoration,
      type: TO_RICOS_DECORATION_TYPE[type as keyof typeof TO_RICOS_DECORATION_TYPE],
    });
  if (data === undefined) {
    // oxlint-disable-next-line no-console
    throw Error(`ERROR! Unknown entity type "${type}"!`);
  }

  const mutability =
    ENTITY_DECORATION_TO_MUTABILITY[type as keyof typeof ENTITY_DECORATION_TO_MUTABILITY];
  return createEntity(entityKey, { type, mutability, data });
};

const getDynamicStyles = (node: Node) => {
  const data = getDataFieldValue(node);
  const textStyle: any = data && 'textStyle' in data ? data.textStyle : {};
  const { textAlignment, lineHeight } = textStyle || {};
  const { paddingTop, paddingBottom } = node.style || {};
  return {
    textAlignment,
    lineHeight,
    paddingTop,
    paddingBottom,
  };
};

export const createTextBlockData = (node: Node) => {
  const { indentation = 0 } = (getDataFieldValue(node) || {}) as any;
  const { textAlignment, lineHeight, paddingTop, paddingBottom } = getDynamicStyles(node);
  return JSON.parse(
    JSON.stringify({
      textAlignment: textAlignment !== 'AUTO' ? textAlignment?.toLowerCase() : undefined,
      dynamicStyles: (paddingTop || paddingBottom || lineHeight) && {
        'padding-top': paddingTop,
        'padding-bottom': paddingBottom,
        'line-height': lineHeight,
      },
      depth: indentation,
    })
  );
};
